-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.canonical_path_malignant_events_v1_invasion_clean
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.canonical_path_malignant_events_v1_invasion_clean AS WITH norm AS (SELECT e.*, lower(main."trim"(regexp_replace(COALESCE(e.margin_status, ''), '\s+', ' ', 'g'))) AS _m, lower(main."trim"(regexp_replace(COALESCE(e.capsular_invasion, ''), '\s+', ' ', 'g'))) AS _c, lower(main."trim"(regexp_replace(COALESCE(e.extranodal_extension, ''), '\s+', ' ', 'g'))) AS _e, lower(main."trim"(regexp_replace(COALESCE(e.lymphatic_invasion, ''), '\s+', ' ', 'g'))) AS _l, lower(main."trim"(regexp_replace(COALESCE(e.perineural_invasion, ''), '\s+', ' ', 'g'))) AS _p, lower(main."trim"(regexp_replace(COALESCE(e.vascular_invasion, ''), '\s+', ' ', 'g'))) AS _v FROM main.canonical_path_malignant_events_v1 AS e)SELECT n.* EXCLUDE (_v, _l, _m, _e, _p, _c), n.margin_status AS margin_status_raw, n.capsular_invasion AS capsular_invasion_raw, n.extranodal_extension AS extranodal_extension_raw, n.lymphatic_invasion AS lymphatic_invasion_raw, n.perineural_invasion AS perineural_invasion_raw, n.vascular_invasion AS vascular_invasion_raw, CASE  WHEN (((n._m = '') OR (n._m IS NULL))) THEN (NULL) WHEN ((n._m IN ('involved', 'involvd', 'present'))) THEN ('positive') WHEN ((n._m IN ('c/a', '<1', '1', '0.1'))) THEN ('close') WHEN ((n._m IN ('indeterminate', 'n/s'))) THEN ('indeterminate') WHEN ((n._m IN ('x', 'negative'))) THEN ('negative') ELSE 'other' END AS margin_status_clean, CASE  WHEN (((n._c = '') OR (n._c IS NULL))) THEN (NULL) WHEN (((n._c ~~ '%widely invasive%') OR (n._c ~~ '%widely invasivre%') OR (n._c ~~ '%widely invasvie%') OR (n._c ~~ '%invasive%') OR (n._c ~~ '%infiltrative%') OR (n._c ~~ '%multifocal%') OR (n._c ~~ '%multiple foci%'))) THEN ('widely_invasive') WHEN (((n._c ~~ '%minimally invasive%') OR (n._c ~~ '%miinimally%') OR (n._c ~~ '%minimally invasvie%') OR (n._c ~~ '%minimallyinvasive%') OR (n._c = 'minimal') OR (n._c ~~ 'minimal %') OR (n._c ~~ '%(minimal%') OR (n._c ~~ '%minimal;%') OR (n._c ~~ '%minimal%)') OR (n._c = 'focal') OR (n._c ~~ '%(focal%') OR (n._c = 'single focus') OR (n._c = 'c/a') OR (n._c = 'into but not through') OR (n._c ~~ '%into but not through%') OR (n._c = 'm'))) THEN ('minimally_invasive') WHEN (((n._c ~~ '%present%') OR (n._c ~~ '%preesent%') OR (n._c ~~ '%preseent%') OR (n._c ~~ '%preent%') OR (n._c ~~ '%prewent%') OR (n._c = 'yes') OR (n._c = 'yes;') OR (n._c ~~ 'yes;%'))) THEN ('present_nos') WHEN ((n._c IN ('indeterminate', 'cannot be assessed', 'equivocal', 'n/s', 'n/s;', 'infiltrative?', 'none?'))) THEN ('indeterminate') WHEN ((n._c IN ('x', 'no', 'no;', 'none', 'n/a'))) THEN ('negative') ELSE 'other' END AS capsular_invasion_clean, CASE  WHEN (((n._e = '') OR (n._e IS NULL))) THEN (NULL) WHEN (((n._e ~~ 'present%') OR (n._e ~~ '%extensive%') OR (n._e = 'yes') OR (n._e = 'focal') OR (n._e ~~ 'focal%') OR (n._e = 'minimal') OR (n._e = 'suspected'))) THEN ('present') WHEN ((n._e IN ('indeterminate', 'equivocal', 'n/s', 'ns', 'c/a'))) THEN ('indeterminate') WHEN ((n._e IN ('x', 'no', 'none'))) THEN ('negative') ELSE 'other' END AS extranodal_extension_clean, CASE  WHEN (((n._l = '') OR (n._l IS NULL))) THEN (NULL) WHEN (((n._l ~~ '%extensive%') OR (n._l ~~ '%extensivre%') OR (n._l ~~ '%extensiver%'))) THEN ('extensive') WHEN (((n._l = 'focal') OR (n._l = '1 focus'))) THEN ('focal') WHEN (((n._l ~~ '%present%') OR (n._l ~~ '%preesent%'))) THEN ('present') WHEN (((n._l IN ('indeterminate', 'indeeterminate', 'indetermiante', 'indeterminent', 'n/s', 'c/a', 'suspicious')) OR (n._l ~~ 'cannot be determined%'))) THEN ('indeterminate') WHEN ((n._l IN ('x', 'no'))) THEN ('negative') ELSE 'other' END AS lymphatic_invasion_clean, CASE  WHEN (((n._p = '') OR (n._p IS NULL))) THEN (NULL) WHEN ((n._p = 'focal')) THEN ('focal') WHEN ((n._p ~~ '%present%')) THEN ('present') WHEN ((n._p IN ('indeterminate', 'c/a'))) THEN ('indeterminate') WHEN ((n._p = 'x')) THEN ('negative') ELSE 'other' END AS perineural_invasion_clean, CASE  WHEN (((n._v = '') OR (n._v IS NULL))) THEN (NULL) WHEN (((n._v ~~ '%extensive%') OR (n._v ~~ '%extrensive%') OR (n._v ~~ '%estensive%') OR (n._v = 'prominent') OR (n._v = 'multifocal'))) THEN ('extensive') WHEN (((n._v = 'focal') OR (n._v = 'foacl') OR (n._v = 'minimal') OR (n._v = 'limited') OR (n._v = 's'))) THEN ('focal') WHEN (((n._v ~~ '%present%') OR (n._v ~~ '%presnt%') OR (n._v ~~ '%preent%') OR (n._v = 'identified'))) THEN ('present') WHEN ((n._v IN ('indeterminate', 'suspicious', 'c/a'))) THEN ('indeterminate') WHEN ((n._v = 'x')) THEN ('negative') ELSE 'other' END AS vascular_invasion_clean FROM norm AS n;
